html:
{%- set b = get_recipe_branding() -%}
<style>
 .hk-cr { font-family: "Open Sans", Arial, "PingFang HK", "Microsoft JhengHei", sans-serif; color: #211f20; font-size: 12px; line-height: 1.45; }
 .hk-cr h2 { font-size: 18px; margin: 0; }
 .hk-cr .muted { color: #6b6b6b; }
 .hk-cr table { width: 100%; border-collapse: collapse; margin-top: 10px; }
 .hk-cr th, .hk-cr td { border: 1px solid #cfcfcf; padding: 5px 6px; vertical-align: top; text-align: left; }
 .hk-cr th { background: #f3f3f3; }
 .hk-cr .fail { color: #b42318; font-weight: 600; }
 .hk-cr .pass { color: #067647; }
 .hk-cr .head td { border: none; padding: 2px 0; }
 .hk-cr img.ph { max-width: 120px; max-height: 90px; }
</style>
<div class="hk-cr">
 <h2>{{ doc.title }} {% set zh = frappe.db.get_value("Checklist Template", doc.template, "title_zh") %}{% if zh %}<span class="muted">{{ zh }}</span>{% endif %}</h2>
 <div class="muted">{{ b.brand_name }} · Kitchen Checks record 廚房檢查記錄 · {{ doc.name }}</div>
 <table class="head">
  <tr><td><b>Area 區域:</b> {{ doc.area }}</td><td><b>Date 日期:</b> {{ frappe.utils.formatdate(doc.run_date) }}</td>
      <td><b>Due 限時:</b> {{ (doc.window_start or "")|string|truncate(16, True, "") }} – {{ (doc.window_end or "")|string|truncate(16, True, "") }}</td></tr>
  <tr><td><b>Signed by 簽署:</b> {{ doc.employee_name or "—" }}</td><td><b>Signed at 時間:</b> {{ (doc.signed_at or "—")|string|truncate(16, True, "") }}{% if doc.late %} <span class="fail">Late 遲</span>{% endif %}</td>
      <td><b>Status 狀態:</b> {{ doc.status }}{% if doc.issues %} · <span class="fail">{{ doc.issues }} failed 不合格</span>{% endif %}</td></tr>
  {% if doc.reviewer %}<tr><td colspan="3"><b>Reviewed by 覆核:</b> {{ doc.reviewer }} · {{ (doc.reviewed_at or "")|string|truncate(16, True, "") }}{% if doc.review_note %} · {{ doc.review_note }}{% endif %}</td></tr>{% endif %}
 </table>
 <table>
  <thead><tr><th style="width:4%">#</th><th style="width:34%">Question 問題</th><th style="width:12%">Allowed 合格</th><th style="width:14%">Answer 答案</th><th style="width:8%">Result 結果</th><th>What was done / note 跟進／備註</th></tr></thead>
  <tbody>
  {% for a in doc.answers %}
   <tr>
    <td>{{ a.idx }}</td>
    <td>{{ a.prompt }}{% if a.critical %} ⚠{% endif %}{% if a.prompt_zh %}<br><span class="muted">{{ a.prompt_zh }}</span>{% endif %}</td>
    <td>{% if a.answer_type == "Number" %}{{ limits_text(a.as_dict()) }}{% elif a.answer_type == "Yes/No" %}{{ a.expected or "Yes" }}{% endif %}</td>
    <td>{{ a.value or "" }}{% if a.photo %}<br><img class="ph" src="{{ a.photo }}">{% endif %}</td>
    <td class="{{ 'fail' if a.result == 'Fail' else 'pass' }}">{{ a.result or "" }}</td>
    <td>{{ a.corrective_action or "" }}{% if a.note %}<br><span class="muted">{{ a.note }}</span>{% endif %}</td>
   </tr>
  {% endfor %}
  </tbody>
 </table>
</div>
